insert into public.exercises (slug, phase, sort, default_sets, default_reps, default_hold_sec, content) values
('quadset', 1, 1, 3, 10, 5, '{"en": {"name": "Quad sets", "steps": ["Lie on your back with both legs straight. Place a small rolled towel under the operated knee.", "Tighten the muscle on the front of your thigh and press the back of the knee down into the towel.", "Hold while keeping the muscle tight, then relax."], "tip": "With your hand on the thigh you should feel the muscle tighten and the kneecap glide upward.", "caution": "Do not push into sharp knee pain. If you feel strong pain or numbness, stop and contact your therapist."}, "ar": {"name": "شدّ عضلة الفخذ", "steps": ["نام على ضهرك والرجلين مفرودين، وحط فوطة ملفوفة صغيرة تحت الركبة المصابة.", "شدّ عضلة الفخذ الأمامية واضغط الركبة لتحت على الفوطة.", "اثبت وانت شادد، وبعدين ارخي."], "tip": "لو حطيت إيدك على الفخذ هتحس العضلة بتتشد وصابونة الركبة بتتحرك لفوق.", "caution": "ماتضغطش لدرجة ألم حاد في الركبة. لو حسيت بوجع جامد أو تنميل، وقّف وكلّم الأخصائي."}, "de": {"name": "Quadrizeps-Anspannung", "steps": ["Legen Sie sich auf den Rücken, beide Beine gestreckt. Legen Sie ein kleines gerolltes Handtuch unter das operierte Knie.", "Spannen Sie den vorderen Oberschenkelmuskel an und drücken Sie die Kniekehle in das Handtuch.", "Halten Sie die Spannung und entspannen Sie dann."], "tip": "Mit der Hand auf dem Oberschenkel spüren Sie, wie sich der Muskel anspannt und die Kniescheibe nach oben gleitet.", "caution": "Nicht in einen stechenden Knieschmerz hineindrücken. Bei starken Schmerzen oder Taubheit aufhören und Ihre Therapeutin / Ihren Therapeuten kontaktieren."}}'::jsonb),
('slr', 1, 2, 3, 10, 3, '{"en": {"name": "Straight leg raise", "steps": ["Lie on your back, bend the healthy knee and keep that foot flat on the floor.", "Tighten the thigh of the operated leg until the knee is fully straight.", "Lift the straight leg up to the height of the other knee and hold.", "Lower it slowly and rest two seconds before the next repetition."], "tip": "Keep the knee fully straight the whole time the leg is up.", "caution": "If the knee bends while lifting or you cannot straighten it fully, do not lift – go back to quad sets."}, "ar": {"name": "رفع الرجل مفرودة", "steps": ["نام على ضهرك، واثني الركبة السليمة وحط رجلك على الأرض.", "شدّ عضلة الفخذ للرجل المصابة لحد ما الركبة تتفرد على الآخر.", "ارفع الرجل وهي مفرودة لحد مستوى الركبة التانية واثبت.", "نزّلها ببطء وارتاح ثانيتين قبل التكرار الجاي."], "tip": "خلّي الركبة مفرودة طول ما الرجل مرفوعة.", "caution": "لو الركبة بتتني وانت بترفع أو مش قادر تفردها على الآخر، ماترفعش الرجل وارجع لتمرين «شدّ عضلة الفخذ»."}, "de": {"name": "Gestrecktes Beinheben", "steps": ["Legen Sie sich auf den Rücken, beugen Sie das gesunde Knie und stellen Sie den Fuß auf.", "Spannen Sie den Oberschenkel des operierten Beins an, bis das Knie ganz gestreckt ist.", "Heben Sie das gestreckte Bein bis auf die Höhe des anderen Knies und halten Sie es.", "Langsam absenken und zwei Sekunden pausieren."], "tip": "Das Knie bleibt die ganze Zeit vollständig gestreckt.", "caution": "Wenn das Knie beim Heben einknickt oder sich nicht ganz strecken lässt: nicht heben, sondern zur Quadrizeps-Anspannung zurückkehren."}}'::jsonb),
('heelslide', 1, 3, 3, 15, 2, '{"en": {"name": "Heel slides", "steps": ["Lie on your back with both legs straight.", "Slide the heel of the operated leg toward you along the floor, bending the knee.", "Hold, then slowly straighten the leg again."], "tip": "Wearing a sock helps the heel slide more easily.", "caution": "Do not bend the knee further than your therapist has allowed. Bend to a mild stretch, not pain."}, "ar": {"name": "سحب الكعب", "steps": ["نام على ضهرك والرجلين مفرودين.", "اسحب كعب الرجل المصابة ناحيتك على الأرض وانت بتثني الركبة.", "اثبت وارجع افرد الرجل ببطء."], "tip": "ممكن تلبس شراب عشان الكعب يتزحلق أسهل.", "caution": "ماتثنيش الركبة أكتر من الدرجة اللي الأخصائي سامحلك بيها. اثني لحد إحساس شد خفيف، مش ألم."}, "de": {"name": "Fersengleiten", "steps": ["Legen Sie sich auf den Rücken, beide Beine gestreckt.", "Ziehen Sie die Ferse des operierten Beins am Boden entlang zu sich heran und beugen Sie dabei das Knie.", "Halten und das Bein langsam wieder strecken."], "tip": "Mit einer Socke gleitet die Ferse leichter.", "caution": "Beugen Sie das Knie nicht weiter, als Ihre Therapeutin / Ihr Therapeut erlaubt hat. Nur bis zu einem leichten Ziehen, nicht bis zum Schmerz."}}'::jsonb),
('pumps', 1, 4, 1, 20, 0, '{"en": {"name": "Ankle pumps", "steps": ["Lie on your back with the leg straight.", "Pull the foot up toward you as far as you can, then point it away.", "Repeat at a steady pace."], "tip": "This helps circulation and reduces swelling.", "caution": "If your calf is swollen, warm or very painful, stop and contact your doctor straight away."}, "ar": {"name": "تحريك القدم لفوق وتحت", "steps": ["نام على ضهرك والرجل مفرودة.", "حرّك القدم لفوق ناحيتك على الآخر، وبعدين لتحت بعيد عنك.", "كرّر بسرعة متوسطة."], "tip": "التمرين ده بيساعد الدورة الدموية ويقلل التورم.", "caution": "لو سمانة الرجل وارمة أو سخنة أو بتوجعك جامد، وقّف التمرين وكلّم الدكتور فورًا."}, "de": {"name": "Sprunggelenk-Pumpe", "steps": ["Legen Sie sich auf den Rücken, das Bein gestreckt.", "Ziehen Sie den Fuß so weit wie möglich zu sich heran und strecken Sie ihn dann von sich weg.", "In gleichmäßigem Tempo wiederholen."], "tip": "Das fördert die Durchblutung und verringert die Schwellung.", "caution": "Wenn Ihre Wade geschwollen, warm oder stark schmerzhaft ist, sofort aufhören und Ihren Arzt / Ihre Ärztin kontaktieren."}}'::jsonb),
('prone', 1, 5, 3, 1, 120, '{"en": {"name": "Prone hangs", "steps": ["Lie on your stomach on the bed with both knees just past the edge.", "Let the weight of the lower leg straighten the knee without tensing.", "Stay for the set time, rest, and repeat."], "tip": "The goal is for the knee to straighten as fully as the healthy one.", "caution": "Do not add an ankle weight unless your therapist told you to. If pain becomes more than mild, shorten the time."}, "ar": {"name": "فرد الركبة على بطنك", "steps": ["نام على بطنك على السرير، والركبتين بره حرف السرير.", "سيب وزن الرجل يفرد الركبة لوحده من غير ما تشدّ.", "افضل كده المدة المكتوبة، وارتاح، وكرّر."], "tip": "الهدف إن الركبة تتفرد على الآخر زي الرجل السليمة.", "caution": "ماتحطش وزن على الكاحل غير لو الأخصائي قالك. لو الألم زاد عن خفيف، قلّل المدة."}, "de": {"name": "Bauchlage-Hängen", "steps": ["Legen Sie sich auf den Bauch, die Knie knapp über die Bettkante.", "Lassen Sie das Gewicht des Unterschenkels das Knie strecken, ohne anzuspannen.", "Für die angegebene Zeit bleiben, pausieren und wiederholen."], "tip": "Ziel ist, dass sich das Knie so weit streckt wie das gesunde.", "caution": "Kein Gewicht am Knöchel, außer Ihre Therapeutin / Ihr Therapeut hat es verordnet. Wird der Schmerz mehr als leicht, die Zeit verkürzen."}}'::jsonb),
('bridge', 1, 6, 3, 10, 3, '{"en": {"name": "Glute bridge", "steps": ["Lie on your back, bend both knees, feet hip-width apart on the floor.", "Squeeze your buttocks and lift the hips until shoulders, hips and knees form a straight line.", "Hold, then lower slowly."], "tip": "Keep your weight evenly on both feet.", "caution": "Do not arch your lower back or lift too high. Stop if you feel strain or pain in the operated knee."}, "ar": {"name": "رفع الحوض", "steps": ["نام على ضهرك، واثني الركبتين والرجلين على الأرض بعرض الحوض.", "شدّ عضلات المقعدة وارفع الحوض لحد ما الجسم يبقى خط مستقيم من الكتف للركبة.", "اثبت ونزّل ببطء."], "tip": "وزنك يبقى على الرجلين بالتساوي.", "caution": "ماتقوّسش ضهرك وماترفعش الحوض زيادة. لو حسيت بشد أو ألم في الركبة المصابة، وقّف."}, "de": {"name": "Beckenheben", "steps": ["Rückenlage, beide Knie gebeugt, Füße hüftbreit aufgestellt.", "Gesäß anspannen und das Becken heben, bis Schultern, Hüfte und Knie eine Linie bilden.", "Halten und langsam absenken."], "tip": "Das Gewicht gleichmäßig auf beide Füße verteilen.", "caution": "Kein Hohlkreuz, nicht zu hoch heben. Bei Ziehen oder Schmerz im operierten Knie aufhören."}}'::jsonb),
('squat', 2, 7, 3, 12, 2, '{"en": {"name": "Mini squats (0–45°)", "steps": ["Stand holding the back of a stable chair, feet shoulder-width apart.", "Bend the knees as if to sit, only to about 45 degrees.", "Stand back up slowly."], "tip": "Keep your weight evenly on both legs.", "caution": "Do not go deeper than 45 degrees. Knees stay behind the toes and must not cave inward. Stop if it hurts."}, "ar": {"name": "نص قرفصاء بالكرسي", "steps": ["اقف وامسك ضهر كرسي ثابت، والرجلين بعرض الكتف.", "انزل كأنك هتقعد لحد ما الركبة تتثني حوالي 45 درجة بس.", "اطلع ببطء."], "tip": "وزنك متوزع على الرجلين بالتساوي.", "caution": "ماتنزلش أكتر من 45 درجة. الركبة ماتعديش صوابع رجلك وماتدخلش لجوه. وقّف لو فيه ألم."}, "de": {"name": "Mini-Kniebeugen (0–45°)", "steps": ["Stellen Sie sich hinter einen stabilen Stuhl und halten Sie sich an der Lehne fest, Füße schulterbreit.", "Beugen Sie die Knie wie zum Hinsetzen, nur bis etwa 45 Grad.", "Langsam wieder aufrichten."], "tip": "Das Gewicht gleichmäßig auf beide Beine verteilen.", "caution": "Nicht tiefer als 45 Grad. Die Knie bleiben hinter den Zehen und knicken nicht nach innen. Bei Schmerz aufhören."}}'::jsonb),
('calf', 2, 8, 3, 15, 2, '{"en": {"name": "Calf raises", "steps": ["Stand holding a wall or a chair.", "Rise up onto the balls of both feet as high as you can.", "Hold, then lower slowly."], "tip": "When it gets easy, do it on the operated leg only.", "caution": "Hold on to something stable so you do not fall."}, "ar": {"name": "الوقوف على المشط", "steps": ["اقف وامسك حيطة أو كرسي.", "اطلع على مشط الرجلين على الآخر.", "اثبت ونزّل ببطء."], "tip": "لما يبقى سهل، اعمله على الرجل المصابة لوحدها.", "caution": "امسك في حاجة ثابتة عشان ماتقعش."}, "de": {"name": "Zehenstand", "steps": ["Halten Sie sich an einer Wand oder einem Stuhl fest.", "Gehen Sie mit beiden Füßen so hoch wie möglich auf die Zehenballen.", "Halten und langsam absenken."], "tip": "Wenn es leicht wird, nur auf dem operierten Bein üben.", "caution": "Halten Sie sich an etwas Stabilem fest, damit Sie nicht stürzen."}}'::jsonb),
('balance', 2, 9, 3, 1, 30, '{"en": {"name": "Single-leg balance", "steps": ["Stand next to a wall or a stable chair.", "Lift the healthy leg and stand on the operated leg with the knee slightly bent.", "Keep your balance for the set time."], "tip": "When it gets easy, try it with your eyes closed.", "caution": "Do it next to something stable, and stop if the knee feels like it is giving way or you might fall."}, "ar": {"name": "الوقوف على رجل واحدة", "steps": ["اقف جنب حيطة أو كرسي ثابت.", "ارفع الرجل السليمة واقف على الرجل المصابة والركبة مثنية ثنية خفيفة.", "حافظ على توازنك المدة المكتوبة."], "tip": "لما يبقى سهل، جرّب وانت مغمّض عينك.", "caution": "اعمله جنب حاجة ثابتة، ووقّف لو حسيت الركبة هتلفّ أو إنك هتقع."}, "de": {"name": "Einbeinstand", "steps": ["Stellen Sie sich neben eine Wand oder einen stabilen Stuhl.", "Heben Sie das gesunde Bein an und stehen Sie auf dem operierten Bein, das Knie leicht gebeugt.", "Halten Sie das Gleichgewicht für die angegebene Zeit."], "tip": "Wenn es leicht wird, mit geschlossenen Augen versuchen.", "caution": "Neben etwas Stabilem üben und aufhören, wenn das Knie nachzugeben droht oder Sie zu stürzen drohen."}}'::jsonb),
('abd', 2, 10, 3, 12, 2, '{"en": {"name": "Side-lying hip abduction", "steps": ["Lie on your healthy side with the operated leg on top.", "Keep the top leg straight and lift it up, toes pointing forward.", "Lower it slowly."], "tip": "The movement comes from the hip; the knee stays straight.", "caution": "Do not roll the pelvis backward, and do not lift the leg higher than needed."}, "ar": {"name": "رفع الرجل على الجنب", "steps": ["نام على جنبك السليم، والرجل المصابة فوق.", "افرد الرجل اللي فوق وارفعها لفوق والصوابع لقدام.", "نزّلها ببطء."], "tip": "الحركة من الحوض، والركبة مفرودة.", "caution": "ماتلفّش الحوض لورا، وماترفعش الرجل أعلى من اللازم."}, "de": {"name": "Abspreizen in Seitenlage", "steps": ["Legen Sie sich auf die gesunde Seite, das operierte Bein oben.", "Heben Sie das obere Bein gestreckt an, die Zehen zeigen nach vorne.", "Langsam absenken."], "tip": "Die Bewegung kommt aus der Hüfte, das Knie bleibt gestreckt.", "caution": "Das Becken nicht nach hinten kippen und das Bein nicht höher als nötig heben."}}'::jsonb),
('hamcurl', 2, 11, 3, 12, 2, '{"en": {"name": "Standing hamstring curl", "steps": ["Stand holding the back of a chair.", "Bend the knee of the operated leg, bringing the heel toward your buttock.", "Lower slowly."], "tip": "Keep the thigh still; it should not move forward.", "caution": "If your surgery used a hamstring tendon graft, only do this once your therapist allows it."}, "ar": {"name": "ثني الركبة واقف", "steps": ["اقف وامسك ضهر كرسي.", "اثني ركبة الرجل المصابة وارفع الكعب ناحية المقعدة.", "نزّل ببطء."], "tip": "الفخذ يفضل ثابت ومايتحركش لقدام.", "caution": "لو عمليتك كانت بوتر الـ hamstring، ماتعملوش غير لما الأخصائي يسمحلك."}, "de": {"name": "Kniebeugen im Stand (Beinbeuger)", "steps": ["Halten Sie sich an einer Stuhllehne fest.", "Beugen Sie das Knie des operierten Beins und führen Sie die Ferse Richtung Gesäß.", "Langsam absenken."], "tip": "Der Oberschenkel bleibt ruhig und bewegt sich nicht nach vorne.", "caution": "Wenn bei Ihrer Operation eine Hamstring-Sehne verwendet wurde, erst üben, wenn Ihre Therapeutin / Ihr Therapeut es erlaubt."}}'::jsonb),
('stepup', 2, 12, 3, 10, 0, '{"en": {"name": "Step-ups", "steps": ["Place the foot of the operated leg on a low step.", "Step up with the operated leg until it is straight.", "Step down slowly, healthy leg first."], "tip": "Hold the handrail if you need to.", "caution": "Start with a low step and hold on to something stable. Stop if the knee hurts or feels unstable."}, "ar": {"name": "الطلوع على درجة", "steps": ["حط رجلك المصابة على درجة سلم واطية.", "اطلع على الدرجة بالرجل المصابة لحد ما تفردها.", "انزل ببطء بالرجل السليمة الأول."], "tip": "امسك الدرابزين لو محتاج.", "caution": "ابدأ بدرجة واطية وامسك في حاجة ثابتة. وقّف لو الركبة وجعتك أو حسيتها مش ثابتة."}, "de": {"name": "Aufsteigen auf eine Stufe", "steps": ["Stellen Sie den Fuß des operierten Beins auf eine niedrige Stufe.", "Steigen Sie mit dem operierten Bein hinauf, bis es gestreckt ist.", "Langsam wieder hinuntersteigen, das gesunde Bein zuerst."], "tip": "Bei Bedarf am Geländer festhalten.", "caution": "Mit einer niedrigen Stufe beginnen und sich an etwas Stabilem festhalten. Aufhören, wenn das Knie schmerzt oder sich instabil anfühlt."}}'::jsonb)
